fast_pseudocode:
# CORRECT: grid must be lambda reading META for autotune to work properly
@triton.autotune(
    configs=[
        triton.Config({'YBLOCK': 8, 'XBLOCK': 128}, num_warps=4, num_stages=3),
        # ... configs ...
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    ...

# Grid must read META so autotune tile sizes actually control grid dimensions
grid = lambda META: (cdiv(xnumel, META['XBLOCK']), cdiv(ynumel, META['YBLOCK']))
kernel[grid](in_ptr, out_ptr, 30, 50176)

